INSERT INTO DimSecurity (SK_SecurityID, Symbol, Issue, Status, Name, ExchangeID, SK_CompanyID, SharesOutstanding, FirstTrade, FirstTradeOnExchange, Dividend, IsCurrent, BatchID, EffectiveDate, EndDate) WITH SecurityRecords AS (SELECT F.Symbol AS Symbol, F.IssueType AS Issue, ST.ST_NAME AS Status, F.Name AS Name, F.ExID AS ExchangeID, F.CoNameOrCIK AS CoNameOrCIK, TRY_CAST(F.ShOut AS INT) AS SharesOutstanding, CAST(TRY_STRPTIME(F.FirstTradeDate, '%Y%m%d') AS DATE) AS FirstTrade, CAST(TRY_STRPTIME(F.FirstTradeExchg, '%Y%m%d') AS DATE) AS FirstTradeOnExchange, TRY_CAST(F.Dividend AS DECIMAL(18, 3)) AS Dividend, STRPTIME(F.PTS, '%Y%m%d-%H%M%S') AS EffectiveTS FROM Source.FinwireSEC AS F INNER JOIN Source.StatusType AS ST ON F.Status = ST.ST_ID WHERE F.RecType = 'SEC'), SecurityCompany AS (SELECT R.*, (SELECT DimCo.CompanyID FROM DimCompany AS DimCo WHERE (CASE WHEN NOT TRY_CAST(R.CoNameOrCIK AS BIGINT) IS NULL THEN DimCo.CompanyID = TRY_CAST(R.CoNameOrCIK AS BIGINT) ELSE DimCo.Name = R.CoNameOrCIK END) AND DimCo.EffectiveDate <= R.EffectiveTS AND R.EffectiveTS < DimCo.EndDate ORDER BY DimCo.EffectiveDate LIMIT 1) AS CompanyID FROM SecurityRecords AS R), SecuritySegments AS (SELECT Symbol, CompanyID, CAST(EffectiveTS AS DATE) AS SegStart, LEAD(CAST(EffectiveTS AS DATE)) OVER (PARTITION BY Symbol ORDER BY EffectiveTS) AS SegEnd FROM SecurityCompany WHERE NOT CompanyID IS NULL), SecurityTimeline AS (SELECT Symbol, CompanyID, EffectiveTS, Issue, Status, Name, ExchangeID, SharesOutstanding, FirstTrade, FirstTradeOnExchange, Dividend FROM SecurityCompany WHERE NOT CompanyID IS NULL UNION ALL SELECT G.Symbol, G.CompanyID, CAST(DimCo.EffectiveDate AS TIMESTAMP) + INTERVAL '23 hours 59 minutes 59 seconds' AS EffectiveTS, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL FROM SecuritySegments AS G INNER JOIN DimCompany AS DimCo ON DimCo.CompanyID = G.CompanyID AND DimCo.EffectiveDate > G.SegStart AND (G.SegEnd IS NULL OR DimCo.EffectiveDate < G.SegEnd)), SecurityFilled AS (SELECT Symbol, EffectiveTS, LAST_VALUE(CompanyID IGNORE NULLS) OVER w AS CompanyID, LAST_VALUE(Issue IGNORE NULLS) OVER w AS Issue, LAST_VALUE(Status IGNORE NULLS) OVER w AS Status, LAST_VALUE(Name IGNORE NULLS) OVER w AS Name, LAST_VALUE(ExchangeID IGNORE NULLS) OVER w AS ExchangeID, LAST_VALUE(SharesOutstanding IGNORE NULLS) OVER w AS SharesOutstanding, LAST_VALUE(FirstTrade IGNORE NULLS) OVER w AS FirstTrade, LAST_VALUE(FirstTradeOnExchange IGNORE NULLS) OVER w AS FirstTradeOnExchange, LAST_VALUE(Dividend IGNORE NULLS) OVER w AS Dividend FROM SecurityTimeline WINDOW w AS (PARTITION BY Symbol ORDER BY EffectiveTS ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), SecurityDaily AS (SELECT * FROM SecurityFilled QUALIFY ROW_NUMBER() OVER (PARTITION BY Symbol, CAST(EffectiveTS AS DATE) ORDER BY EffectiveTS DESC) = 1), SecurityFinal AS (SELECT D.Symbol, D.Issue, D.Status, D.Name, D.ExchangeID, DimCo.SK_CompanyID AS SK_CompanyID, D.SharesOutstanding, D.FirstTrade, D.FirstTradeOnExchange, D.Dividend, CAST(D.EffectiveTS AS DATE) AS EffectiveDate FROM SecurityDaily AS D LEFT JOIN DimCompany AS DimCo ON DimCo.CompanyID = D.CompanyID AND DimCo.EffectiveDate <= CAST(D.EffectiveTS AS DATE) AND CAST(D.EffectiveTS AS DATE) < DimCo.EndDate) SELECT ROW_NUMBER() OVER (ORDER BY Symbol, EffectiveDate) AS SK_SecurityID, Symbol, Issue, Status, Name, ExchangeID, SK_CompanyID, SharesOutstanding, FirstTrade, FirstTradeOnExchange, Dividend, CASE WHEN LEAD(EffectiveDate) OVER (PARTITION BY Symbol ORDER BY EffectiveDate ASC) IS NULL THEN TRUE ELSE FALSE END AS IsCurrent, 1 AS BatchID, EffectiveDate, COALESCE(LEAD(EffectiveDate) OVER (PARTITION BY Symbol ORDER BY EffectiveDate ASC), CAST('9999-12-31' AS DATE)) AS EndDate FROM SecurityFinal ORDER BY Symbol, EffectiveDate